            ExitCode::from(2)
        }
        cli::ParseOutcome::Args(parsed) => {
            match runner::dispatch(parsed) {
                Ok(code) => ExitCode::from(code as u8),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    let mut src = e.source();
                    while let Some(s) = src {
                        eprintln!();
                        eprintln!("Caused by:");
                        eprintln!("    {}", s);
                        src = s.source();
                    }
                    ExitCode::from(1)
                }
            }
        }
    }
}

