//! CLI argument parsing (hand-rolled to match clap's format).

pub struct ParsedArgs {
    pub lang: Option<String>,
    pub code: Option<String>,
    pub file: Option<String>,
    pub no_detect: bool,
    pub positionals: Vec<String>,
}

pub enum ParseOutcome {
    Help,
    Version,
    Args(ParsedArgs),
    Error(String),
}

pub fn parse_args(argv: &[String]) -> ParseOutcome {
    let mut lang: Option<String> = None;
    let mut code: Option<String> = None;
    let mut file: Option<String> = None;
    let mut no_detect = false;
    let mut positionals: Vec<String> = Vec::new();

    let mut saw_dash_dash = false;
    let mut i = 1;
    while i < argv.len() {
        let a = &argv[i];
        if saw_dash_dash {
            positionals.push(a.clone());
            i += 1;
            continue;
        }
        if a == "--" {
            saw_dash_dash = true;
            i += 1;
            continue;
        }
        if a == "-h" || a == "--help" {
            return ParseOutcome::Help;
        }
        if a == "-V" || a == "--version" {
            return ParseOutcome::Version;
        }
        if a == "--no-detect" {
            no_detect = true;
            i += 1;
            continue;
        }

        // Option with value
        if let Some(val) = opt_value(a, "-l", "--lang") {
            match val {
                OptVal::Inline(v) => {
                    if v.is_empty() {
                        return ParseOutcome::Error(val_required_err("--lang <LANG>"));
                    }
                    lang = Some(v);
                    i += 1;
                }
                OptVal::Next => {
                    if i + 1 >= argv.len() || argv[i + 1].is_empty() {
                        return ParseOutcome::Error(val_required_err("--lang <LANG>"));
                    }
                    lang = Some(argv[i + 1].clone());
                    i += 2;
                }
            }
            continue;
        }
        if let Some(val) = opt_value(a, "-f", "--file") {
            match val {
                OptVal::Inline(v) => {
                    if v.is_empty() {
                        return ParseOutcome::Error(val_required_err("--file <PATH>"));
                    }
                    file = Some(v);
                    i += 1;
                }
                OptVal::Next => {
                    if i + 1 >= argv.len() || argv[i + 1].is_empty() {
                        return ParseOutcome::Error(val_required_err("--file <PATH>"));
                    }
                    file = Some(argv[i + 1].clone());
                    i += 2;
                }
            }
            continue;
        }
        if let Some(val) = opt_value(a, "-c", "--code") {
            match val {
                OptVal::Inline(v) => {
                    if v.is_empty() {
                        return ParseOutcome::Error(val_required_err("--code <CODE>"));
                    }
                    code = Some(v);
                    i += 1;
                }
                OptVal::Next => {
                    if i + 1 >= argv.len() || argv[i + 1].is_empty() {
                        return ParseOutcome::Error(val_required_err("--code <CODE>"));
                    }
                    code = Some(argv[i + 1].clone());
                    i += 2;
                }
            }
            continue;
        }

        // Unknown flag check
        if a.starts_with("--") || (a.len() > 1 && a.starts_with('-') && !is_numeric_like(a)) {
            // If we already have positionals, treat as positional (trailing_var_arg)
            if !positionals.is_empty() {
                positionals.push(a.clone());
                i += 1;
                continue;
            }
            return ParseOutcome::Error(unknown_arg_err(a));
        }

        // Positional
        positionals.push(a.clone());
        i += 1;
    }

    ParseOutcome::Args(ParsedArgs {
        lang,
        code,
        file,
        no_detect,
        positionals,
    })
}

enum OptVal {
    Inline(String),
    Next,
}

fn opt_value(arg: &str, short: &str, long: &str) -> Option<OptVal> {
    if arg == short || arg == long {
        return Some(OptVal::Next);
    }
    if let Some(v) = arg.strip_prefix(&format!("{}=", long)) {
        return Some(OptVal::Inline(v.to_string()));
    }
    if let Some(v) = arg.strip_prefix(&format!("{}=", short)) {
        return Some(OptVal::Inline(v.to_string()));
    }
    if short.len() == 2 && arg.starts_with(short) && arg.len() > 2 {
        // -lPython style (combined)
        return Some(OptVal::Inline(arg[2..].to_string()));
    }
    None
}

fn is_numeric_like(a: &str) -> bool {
    // allow "-1" etc as positional - not an unknown flag
    a.chars().skip(1).all(|c| c.is_ascii_digit() || c == '.')
}

fn val_required_err(name: &str) -> String {
    format!(
        "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
        name
    )
}

fn unknown_arg_err(a: &str) -> String {
    format!(
        "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [ARGS]...\n\nFor more information, try '--help'.\n",
        a, a, a
    )
}

