//! Heuristic language detection from code content.

use crate::lang::Lang;

/// Very small set of regex-free heuristics. We check patterns in priority order
/// and return the first match. This mirrors empirically-observed behaviour of
/// the reference implementation for common cases.
pub fn detect_from_content(code: &str) -> Option<Lang> {
    // Normalize: examine line by line (not whitespace)
    let src = code.trim_start_matches('\u{FEFF}');
    let first_non_empty = src.lines().find(|l| !l.trim().is_empty()).unwrap_or("").trim_start();
    let lower = src.to_lowercase();

    // Shebang handling.
    if first_non_empty.starts_with("#!") {
        let rest = &first_non_empty[2..];
        if rest.contains("bash") || rest.contains("/sh") || rest.ends_with("/sh") || rest.contains("/sh ") {
            return Some(Lang::Bash);
        }
        if rest.contains("python") { return Some(Lang::Python); }
        if rest.contains("ruby") { return Some(Lang::Ruby); }
        if rest.contains("perl") { return Some(Lang::Perl); }
        if rest.contains("node") { return Some(Lang::Javascript); }
        if rest.contains("lua") { return Some(Lang::Lua); }
        if rest.contains("php") { return Some(Lang::Php); }
    }

    // <?php
    if src.trim_start().starts_with("<?php") || src.contains("<?php") {
        return Some(Lang::Php);
    }

    // Strong multi-word markers.
    if line_matches(src, |l| l.starts_with("package main") || l.starts_with("package ") && l.contains(".")) {
        return Some(Lang::Go);
    }
    if line_matches(src, |l| l.starts_with("package main")) {
        return Some(Lang::Go);
    }
    if line_matches(src, |l| l.starts_with("import \"") && l.contains("\"")) {
        return Some(Lang::Go);
    }
    if line_matches(src, |l| l.starts_with("func main(") || l.starts_with("func main ") || l == "func main") {
        return Some(Lang::Go);
    }
    if line_matches(src, |l| l.starts_with("pub fn main(")) {
        return Some(Lang::Zig);
    }
    if line_matches(src, |l| l.starts_with("fn main(")) {
        return Some(Lang::Rust);
    }
    if contains_word(&lower, "println!") {
        return Some(Lang::Rust);
    }
    if contains_word(&lower, "defmodule") {
        return Some(Lang::Elixir);
    }
    if lower.contains("io.puts") {
        return Some(Lang::Elixir);
    }
    if line_matches(src, |l| l.starts_with("defmodule ")) {
        return Some(Lang::Elixir);
    }
    if line_matches(src, |l| l.starts_with("using System") || l.starts_with("using System.")) {
        return Some(Lang::Csharp);
    }
    if line_matches(src, |l| l.starts_with("public class ") || l.starts_with("public static void main")) {
        return Some(Lang::Java);
    }
    if line_matches(src, |l| l.starts_with("fun main(") || l.starts_with("import * as ")) {
        return Some(Lang::Kotlin);
    }
    if line_matches(src, |l| l.starts_with("void main(") || l == "void main") {
        return Some(Lang::Dart);
    }
    if line_matches(src, |l| l.starts_with("interface ")) {
        return Some(Lang::Typescript);
    }
    if line_matches(src, |l| l.starts_with("function ") && l.contains("(")) {
        return Some(Lang::Javascript);
    }
    if lower.contains("console.log") {
        return Some(Lang::Javascript);
    }
    if line_matches(src, |l| l.starts_with("#include <") || l.starts_with("std::") || l.starts_with("int main(")) {
        return Some(Lang::Cpp);
    }
    if line_matches(src, |l| l.starts_with("#include \"")) {
        return Some(Lang::R);
    }
    if line_matches(src, |l| l.starts_with("# ")) {
        return Some(Lang::R);
    }
    if line_matches(src, |l| l.starts_with("require(")) {
        return Some(Lang::R);
    }
    if line_matches(src, |l| l.starts_with("require \"") || l.starts_with("require '")) {
        return Some(Lang::Ruby);
    }
    if line_matches(src, |l| l.starts_with("module ")) {
        return Some(Lang::Ruby);
    }
    if line_matches(src, |l| l.starts_with("puts ") || l == "puts") {
        return Some(Lang::Ruby);
    }
    if line_matches(src, |l| l.starts_with("var ") && (l.contains(": int") || l.contains(": string") || l.contains(": float") || l.contains(": bool"))) {
        return Some(Lang::Nim);
    }
    if line_matches(src, |l| l.starts_with("main = ") || l.starts_with("main = do")) {
        return Some(Lang::Haskell);
    }
    if line_matches(src, |l| l.starts_with("let ") && !l.starts_with("let mut") && !l.ends_with(";")) {
        return Some(Lang::Haskell);
    }
    if line_matches(src, |l| l.starts_with("my $") || l.starts_with("sub ") || l.starts_with("use strict") || l.starts_with("use warnings")) {
        return Some(Lang::Perl);
    }
    // `print ...` (with space not parens) → Perl
    if line_matches(src, |l| l.starts_with("print ") || l.starts_with("print\t")) {
        return Some(Lang::Perl);
    }
    if line_matches(src, |l| l.starts_with("println(")) {
        return Some(Lang::Julia);
    }
    // `echo "..."` with double-quoted string → PHP; bare echo → bash
    if line_matches(src, |l| l.starts_with("echo \"")) {
        return Some(Lang::Php);
    }
    if line_matches(src, |l| l.starts_with("echo ") || l.starts_with("export ")) {
        return Some(Lang::Bash);
    }
    // `print(...)` with parens on its own is commonly Lua
    if line_matches(src, |l| l.starts_with("print(")) {
        return Some(Lang::Lua);
    }

    None
}

/// Check whether any non-empty line (trimmed) matches predicate.
fn line_matches<F>(src: &str, f: F) -> bool
where
    F: Fn(&str) -> bool,
{
    for line in src.lines() {
        let t = line.trim_start();
        if t.is_empty() {
            continue;
        }
        if f(t) {
            return true;
        }
    }
    false
}

fn contains_word(hay: &str, needle: &str) -> bool {
    hay.contains(needle)
}
