//! Very small tempdir helper (no external crates).

use std::io;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};

pub fn make_dir(prefix: &str) -> io::Result<PathBuf> {
    let mut attempts = 0u32;
    loop {
        let suffix = rand_suffix();
        let name = format!("{}{}", prefix, suffix);
        let p = PathBuf::from("/tmp").join(name);
        match std::fs::create_dir(&p) {
            Ok(()) => return Ok(p),
            Err(e) => {
                attempts += 1;
                if attempts > 64 {
                    return Err(e);
                }
            }
        }
    }
}

fn rand_suffix() -> String {
    // 6-char base-62 suffix seeded from process id and time.
    const ALPH: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
    let mut seed = (now.as_nanos() as u64) ^ (std::process::id() as u64).rotate_left(17);
    // Mix a counter so repeated calls within the same nanosecond still differ.
    static COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let c = COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    seed ^= c.wrapping_mul(0x9e3779b97f4a7c15);
    let mut out = String::new();
    let mut s = seed;
    for _ in 0..6 {
        let i = (s % ALPH.len() as u64) as usize;
        out.push(ALPH[i] as char);
        s = s.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
    }
    out
}
