fn groovy_wrap(code: &str) -> String {
    // If the last non-empty line starts with `print`/`println` + `(` or whitespace, use as-is.
    // Otherwise append `\nprintln(<lastline>);` so expression values show up.
    let trimmed = code.trim_end_matches('\n');
    let lines: Vec<&str> = trimmed.lines().collect();
    let last = lines.iter().rev().find(|l| !l.trim().is_empty()).map(|s| *s).unwrap_or("");
    let last_trim = last.trim_start();
    let starts_with_print = is_printy(last_trim);
    if starts_with_print {
        return trimmed.to_string();
    }
    format!("{}\nprintln({});\n", trimmed, last_trim)
}
fn is_printy(s: &str) -> bool {
    // start with println or print followed by (, space, tab or end
    if let Some(rest) = s.strip_prefix("println") {
        if rest.is_empty() || rest.starts_with('(') || rest.starts_with(char::is_whitespace) {
            return true;
        }
    }
    if let Some(rest) = s.strip_prefix("print") {
        if rest.is_empty() || rest.starts_with('(') || rest.starts_with(char::is_whitespace) {
            return true;
        }
    }
    false
}
