//! Dispatches the parsed CLI to the right execution strategy.

use crate::cli::ParsedArgs;
use crate::detect;
use crate::lang::{self, Lang};
use crate::repl;
use crate::temp;

use std::error::Error as StdError;
use std::fmt;
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::Instant;

#[derive(Debug)]
pub struct AppError {
    pub msg: String,
    pub source: Option<Box<dyn StdError + Send + Sync + 'static>>,
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.msg)
    }
}

impl StdError for AppError {
    fn source(&self) -> Option<&(dyn StdError + 'static)> {
        self.source.as_ref().map(|b| b.as_ref() as &dyn StdError)
    }
}

impl AppError {
    pub fn msg(s: impl Into<String>) -> Self {
        Self { msg: s.into(), source: None }
    }
    pub fn wrap<E: StdError + Send + Sync + 'static>(s: impl Into<String>, e: E) -> Self {
        Self { msg: s.into(), source: Some(Box::new(e)) }
    }
}

pub type AppResult<T> = std::result::Result<T, AppError>;

pub fn dispatch(args: ParsedArgs) -> AppResult<i32> {
    // Normalize positionals: optionally first is language.
    let mut lang: Option<Lang> = match &args.lang {
        Some(s) => {
            let Some(l) = lang::parse_lang(s) else {
                return Err(AppError::msg(format!(
                    "Unknown language '{}'. Available languages: {}",
                    s.trim(),
                    lang::available_list()
                )));
            };
            Some(l)
        }
        None => None,
    };

    // Guard: --code/--inline cannot be combined with --file
    if args.code.is_some() && args.file.is_some() {
        return Err(AppError::msg("--code/--inline cannot be combined with --file"));
    }

    let mut positionals = args.positionals.clone();
    // If a language wasn't given via -l, consume the first positional if it's one.
    if lang.is_none() && !positionals.is_empty() {
        if let Some(l) = lang::parse_lang(&positionals[0]) {
            lang = Some(l);
            positionals.remove(0);
        }
    }

    if args.code.is_some() && !positionals.is_empty() {
        return Err(AppError::msg("Unexpected positional arguments after specifying --code"));
    }

    // Determine mode: code, file, or REPL/stdin.
    enum Mode {
        Code(String),
        File(PathBuf),
        StdinOrRepl,
    }
    let mode = if let Some(c) = &args.code {
        Mode::Code(c.clone())
    } else if let Some(f) = &args.file {
        Mode::File(PathBuf::from(f))
    } else if !positionals.is_empty() {
        if positionals.len() == 1 {
            let arg = &positionals[0];
            if looks_like_path(arg) {
                Mode::File(PathBuf::from(arg))
            } else {
                Mode::Code(arg.clone())
            }
        } else {
            // Multiple positionals → join as code
            Mode::Code(positionals.join(" "))
        }
    } else {
        Mode::StdinOrRepl
    };

    // Resolve language.
    let effective_lang: Lang = match &mode {
        Mode::File(p) => {
            if let Some(l) = lang {
                l
            } else if !args.no_detect {
                let path_str = p.to_string_lossy();
                if let Some(l) = lang::detect_from_extension(&path_str) {
                    l
                } else {
                    Lang::Python
                }
            } else {
                Lang::Python
            }
        }
        Mode::Code(c) => {
            if let Some(l) = lang {
                l
            } else if !args.no_detect {
                detect::detect_from_content(c).unwrap_or(Lang::Python)
            } else {
                Lang::Python
            }
        }
        Mode::StdinOrRepl => lang.unwrap_or(Lang::Python),
    };

    // Execute.
    match mode {
        Mode::Code(c) => run_inline(effective_lang, &c),
        Mode::File(p) => run_file(effective_lang, &p),
        Mode::StdinOrRepl => {
            // If stdin is a terminal → REPL. Else read stdin as code.
            if is_terminal_stdin() {
                repl::run(effective_lang, !args.no_detect)
            } else {
                let mut buf = String::new();
                std::io::stdin()
                    .read_to_string(&mut buf)
                    .map_err(|e| AppError::wrap("failed to read stdin", e))?;
                // If no language explicitly set, rerun detection on stdin content.
                let ll = if lang.is_none() && !args.no_detect {
                    detect::detect_from_content(&buf).unwrap_or(Lang::Python)
                } else {
                    effective_lang
                };
                run_inline(ll, &buf)
            }
        }
    }
}

fn looks_like_path(a: &str) -> bool {
    if a.contains('/') {
        return true;
    }
    if let Some(idx) = a.rfind('.') {
        let ext = &a[idx + 1..];
        if !ext.is_empty() && lang::ext_to_lang(ext).is_some() {
            return true;
        }
    }
    false
}

fn is_terminal_stdin() -> bool {
    // SAFETY: isatty(0) is safe to call.
    unsafe { libc_isatty(0) != 0 }
}

extern "C" {
