pub fn require_bin(bin: &str, label: &str, url: &str) -> AppResult<()> {
    if which(bin).is_none() {
        return Err(AppError::msg(format!(
            "{} support requires the `{}` executable. Install it from {} and ensure it is on your PATH.",
            label, bin, url
        )));
    }
    Ok(())
}

pub fn require_bin_named(bin: &str, label: &str, url: &str, display_bin: &str) -> AppResult<()> {
    if which(bin).is_none() {
        let tail = match label {
            "Java" => format!(" or your vendor of choice and ensure it is on your PATH."),
            "PHP" => " and ensure it is on your PATH.".into(),
            "Swift" => format!(" and ensure `{}` is on your PATH.", display_bin.split_whitespace().next().unwrap_or(display_bin)),
            _ => format!(" and ensure `{}` is on your PATH.", display_bin.split_whitespace().next().unwrap_or(display_bin)),
        };
        let _ = tail;
        // Use a single canonical format close to the reference messages.
        return Err(match label {
            "Java" => AppError::msg(format!(
                "Java support requires the `javac` compiler. Install the JDK from {} or your vendor of choice and ensure it is on your PATH.", url)),
            "Kotlin" => AppError::msg(format!(
                "Kotlin support requires the `kotlinc` compiler. Install it from {} and ensure it is on your PATH.", url)),
            "PHP" => AppError::msg(format!(
                "PHP support requires the `php` CLI executable. Install PHP and ensure it is on your PATH.")),
            "Swift" => AppError::msg(format!(
                "Swift support requires the `swift` executable. Install Xcode command-line tools or the Swift toolchain from {} and ensure `swift` is on your PATH.", url)),
            "R" => AppError::msg(format!(
                "R support requires the `Rscript` executable. Install R from {} and ensure `Rscript` is on your PATH.", url)),
            "Haskell" => AppError::msg(format!(
                "Haskell support requires the `runghc` executable. Install the GHC toolchain from {} (or via ghcup) and ensure `runghc` is on your PATH.", url)),
            _ => AppError::msg(format!(
                "{} support requires the `{}` executable. Install it from {} and ensure it is on your PATH.", label, bin, url)),
        });
    }
    Ok(())
}

