//! Dispatches the parsed CLI to the right execution strategy.

use crate::cli::ParsedArgs;
use crate::detect;
use crate::lang::{self, Lang};
use crate::repl;
use crate::temp;

use std::error::Error as StdError;
use std::fmt;
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::Instant;

#[derive(Debug)]
pub struct AppError {
    pub msg: String,
    pub source: Option<Box<dyn StdError + Send + Sync + 'static>>,
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.msg)
    }
}

impl StdError for AppError {
    fn source(&self) -> Option<&(dyn StdError + 'static)> {
        self.source.as_ref().map(|b| b.as_ref() as &dyn StdError)
    }
}

impl AppError {
    pub fn msg(s: impl Into<String>) -> Self {
        Self { msg: s.into(), source: None }
    }
    pub fn wrap<E: StdError + Send + Sync + 'static>(s: impl Into<String>, e: E) -> Self {
        Self { msg: s.into(), source: Some(Box::new(e)) }
    }
}

pub type AppResult<T> = std::result::Result<T, AppError>;

pub fn dispatch(args: ParsedArgs) -> AppResult<i32> {
    // Normalize positionals: optionally first is language.
    let mut lang: Option<Lang> = match &args.lang {
        Some(s) => {
            let Some(l) = lang::parse_lang(s) else {
                return Err(AppError::msg(format!(
                    "Unknown language '{}'. Available languages: {}",
                    s.trim(),
                    lang::available_list()
                )));
            };
            Some(l)
        }
        None => None,
    };

    // Guard: --code/--inline cannot be combined with --file
    if args.code.is_some() && args.file.is_some() {
        return Err(AppError::msg("--code/--inline cannot be combined with --file"));
    }

    let mut positionals = args.positionals.clone();
    // If a language wasn't given via -l, consume the first positional if it's one.
    if lang.is_none() && !positionals.is_empty() {
        if let Some(l) = lang::parse_lang(&positionals[0]) {
            lang = Some(l);
            positionals.remove(0);
        }
    }

    if args.code.is_some() && !positionals.is_empty() {
        return Err(AppError::msg("Unexpected positional arguments after specifying --code"));
    }

    // Determine mode: code, file, or REPL/stdin.
    enum Mode {
        Code(String),
        File(PathBuf),
        StdinOrRepl,
    }
    let mode = if let Some(c) = &args.code {
        Mode::Code(c.clone())
    } else if let Some(f) = &args.file {
        Mode::File(PathBuf::from(f))
    } else if !positionals.is_empty() {
        if positionals.len() == 1 {
            let arg = &positionals[0];
            if looks_like_path(arg) {
                Mode::File(PathBuf::from(arg))
            } else {
                Mode::Code(arg.clone())
            }
        } else {
            // Multiple positionals → join as code
            Mode::Code(positionals.join(" "))
        }
    } else {
        Mode::StdinOrRepl
    };

    // Resolve language.
    let effective_lang: Lang = match &mode {
        Mode::File(p) => {
            if let Some(l) = lang {
                l
            } else if !args.no_detect {
                let path_str = p.to_string_lossy();
                if let Some(l) = lang::detect_from_extension(&path_str) {
                    l
                } else {
                    Lang::Python
                }
            } else {
                Lang::Python
            }
        }
        Mode::Code(c) => {
            if let Some(l) = lang {
                l
            } else if !args.no_detect {
                detect::detect_from_content(c).unwrap_or(Lang::Python)
            } else {
                Lang::Python
            }
        }
        Mode::StdinOrRepl => lang.unwrap_or(Lang::Python),
    };

    // Execute.
    match mode {
        Mode::Code(c) => run_inline(effective_lang, &c),
        Mode::File(p) => run_file(effective_lang, &p),
        Mode::StdinOrRepl => {
            // If stdin is a terminal → REPL. Else read stdin as code.
            if is_terminal_stdin() {
                repl::run(effective_lang, !args.no_detect)
            } else {
                let mut buf = String::new();
                std::io::stdin()
                    .read_to_string(&mut buf)
                    .map_err(|e| AppError::wrap("failed to read stdin", e))?;
                // If no language explicitly set, rerun detection on stdin content.
                let ll = if lang.is_none() && !args.no_detect {
                    detect::detect_from_content(&buf).unwrap_or(Lang::Python)
                } else {
                    effective_lang
                };
                run_inline(ll, &buf)
            }
        }
    }
}

fn looks_like_path(a: &str) -> bool {
    if a.contains('/') {
        return true;
    }
    if let Some(idx) = a.rfind('.') {
        let ext = &a[idx + 1..];
        if !ext.is_empty() && lang::ext_to_lang(ext).is_some() {
            return true;
        }
    }
    false
}

fn is_terminal_stdin() -> bool {
    // SAFETY: isatty(0) is safe to call.
    unsafe { libc_isatty(0) != 0 }
}

extern "C" {
    #[link_name = "isatty"]
    fn libc_isatty(fd: i32) -> i32;
}

// --------- language-specific runners ---------

pub fn run_inline(lang: Lang, code: &str) -> AppResult<i32> {
    match lang {
        Lang::Bash => run_bash_inline(code),
        Lang::Python => run_python_inline(code),
        Lang::Perl => run_perl_inline(code),
        Lang::Ruby => run_ruby_inline(code),
        Lang::Javascript => run_js_inline(code),
        Lang::Typescript => run_ts_inline(code, false),
        Lang::Lua => run_lua_inline(code),
        Lang::R => run_r_inline(code),
        Lang::Go => run_go_inline(code),
        Lang::Rust => run_rust_inline(code),
        Lang::C => run_c_inline(code),
        Lang::Cpp => run_cpp_inline(code),
        Lang::Java => run_java_inline(code),
        Lang::Kotlin => run_kotlin_inline(code),
        Lang::Swift => run_swift_inline(code),
        Lang::Haskell => run_haskell_inline(code),
        Lang::Elixir => run_elixir_inline(code),
        Lang::Julia => run_julia_inline(code),
        Lang::Crystal => run_crystal_inline(code),
        Lang::Dart => run_dart_inline(code),
        Lang::Groovy => run_groovy_inline(code),
        Lang::Nim => run_nim_inline(code),
        Lang::Php => run_php_inline(code),
        Lang::Zig => run_zig_inline(code),
        Lang::Csharp => run_csharp_inline(code),
    }
}

pub fn run_file(lang: Lang, path: &Path) -> AppResult<i32> {
    // For most file runs we execute the language's interpreter/compiler
    // with the provided file path.
    match lang {
        Lang::Python => {
            require_bin("python3", "Python", "https://www.python.org/downloads/")?;
            let s = Command::new("python3").arg(path).status();
            Ok(status_exit(s, "python3")?)
        }
        Lang::Bash => {
            require_bin("bash", "Bash", "https://www.gnu.org/software/bash/")?;
            let s = Command::new("bash").arg(path).status();
            Ok(status_exit(s, "bash")?)
        }
        Lang::Perl => {
            require_bin("perl", "Perl", "https://www.perl.org/get.html")?;
            let s = Command::new("perl").arg(path).status();
            Ok(status_exit(s, "perl")?)
        }
        Lang::Ruby => {
            require_bin("ruby", "Ruby", "https://www.ruby-lang.org/en/downloads/")?;
            let s = Command::new("ruby").arg(path).status();
            Ok(status_exit(s, "ruby")?)
        }
        Lang::Javascript => {
            require_bin("node", "Node", "https://nodejs.org/")?;
            let s = Command::new("node").arg(path).status();
            Ok(status_exit(s, "node")?)
        }
        Lang::Typescript => {
            require_deno("file")?;
            let s = Command::new("deno")
                .arg("run").arg("--quiet").arg("--no-check").arg("--ext").arg("ts").arg(path).status();
            Ok(status_exit(s, "deno")?)
        }
        Lang::Lua => {
            require_bin_named("lua", "Lua", "https://www.lua.org/download.html", "lua")?;
            let s = Command::new("lua").arg(path).status();
            Ok(status_exit(s, "lua")?)
        }
        Lang::R => {
            require_bin_named("Rscript", "R", "https://cran.r-project.org/", "Rscript")?;
            let s = Command::new("Rscript").arg("--vanilla").arg(path).status();
            Ok(status_exit(s, "Rscript")?)
        }
        Lang::Php => {
            require_bin_named("php", "PHP", "", "php")?;
            let s = Command::new("php").arg(path).status();
            Ok(status_exit(s, "php")?)
        }
        Lang::Go => {
            require_bin("go", "Go", "https://go.dev/doc/install")?;
            // cd to parent dir so `go run basename` works with package main files
            let parent = path.parent().unwrap_or_else(|| Path::new("."));
            let basename = path.file_name().ok_or_else(|| AppError::msg("invalid path"))?;
            let go_path = which("go").unwrap_or_else(|| PathBuf::from("go"));
            let status = Command::new(&go_path)
                .current_dir(parent)
                .arg("run")
                .arg(basename)
                .status()
                .map_err(|e| AppError::wrap(format!("failed to invoke {} to run {}", go_path.display(), basename.to_string_lossy()), e))?;
            Ok(status.code().unwrap_or(1))
        }
        Lang::Rust => {
            require_bin("rustc", "Rust", "https://www.rust-lang.org/tools/install")?;
            let code = std::fs::read_to_string(path)
                .map_err(|e| AppError::wrap("failed to read file", e))?;
            run_rust_inline_with_name(&code, path.to_string_lossy().as_ref())
        }
        Lang::C => {
            require_cc()?;
            let code = std::fs::read_to_string(path)
                .map_err(|e| AppError::wrap("failed to read file", e))?;
            run_c_inline(&code)
        }
        Lang::Cpp => {
            require_cxx()?;
            let code = std::fs::read_to_string(path)
                .map_err(|e| AppError::wrap("failed to read file", e))?;
            run_cpp_inline(&code)
        }
        Lang::Java => {
            require_bin_named("javac", "Java", "https://adoptium.net/", "javac compiler")?;
            let code = std::fs::read_to_string(path)
                .map_err(|e| AppError::wrap("failed to read file", e))?;
            run_java_inline(&code)
        }
        Lang::Kotlin => {
            require_bin_named("kotlinc", "Kotlin", "https://kotlinlang.org/docs/command-line.html", "kotlinc compiler")?;
            let code = std::fs::read_to_string(path)
                .map_err(|e| AppError::wrap("failed to read file", e))?;
            run_kotlin_inline(&code)
        }
        Lang::Swift => {
            require_bin("swift", "Swift", "https://www.swift.org/download/")?;
            let s = Command::new("swift").arg(path).status();
            Ok(status_exit(s, "swift")?)
        }
        Lang::Haskell => {
            require_bin_named("runghc", "Haskell", "https://www.haskell.org/ghc/", "runghc")?;
            let s = Command::new("runghc").arg(path).status();
            Ok(status_exit(s, "runghc")?)
        }
        Lang::Elixir => {
            require_bin("elixir", "Elixir", "https://elixir-lang.org/install.html")?;
            let s = Command::new("elixir").arg("--no-color").arg(path).status();
            Ok(status_exit(s, "elixir")?)
        }
        Lang::Julia => {
            require_bin("julia", "Julia", "https://julialang.org/downloads/")?;
            let s = Command::new("julia").arg("--color=no").arg("--quiet").arg(path).status();
            Ok(status_exit(s, "julia")?)
        }
        Lang::Crystal => {
            require_bin("crystal", "Crystal", "https://crystal-lang.org/install/")?;
            let s = Command::new("crystal").arg("run").arg(path).arg("--no-color").status();
            Ok(status_exit(s, "crystal")?)
        }
        Lang::Dart => {
            require_bin("dart", "Dart", "https://dart.dev/get-dart")?;
            let s = Command::new("dart").arg("run").arg("--enable-asserts").arg(path).status();
            Ok(status_exit(s, "dart")?)
        }
        Lang::Groovy => {
            require_bin("groovy", "Groovy", "https://groovy-lang.org/download.html")?;
            let s = Command::new("groovy").arg(path).status();
            Ok(status_exit(s, "groovy")?)
        }
        Lang::Nim => {
            require_bin("nim", "Nim", "https://nim-lang.org/install.html")?;
            let s = Command::new("nim").arg("r").arg(path)
                .arg("--colors:off").arg("--hints:off").arg("--verbosity:0").status();
            Ok(status_exit(s, "nim")?)
        }
        Lang::Zig => {
            require_bin("zig", "Zig", "https://ziglang.org/download/")?;
            let s = Command::new("zig").arg("run").arg(path).status();
            Ok(status_exit(s, "zig")?)
        }
        Lang::Csharp => {
            run_csharp_file(path)
        }
    }
}

// ----- helpers for dependency checks -----

pub fn require_bin(bin: &str, label: &str, url: &str) -> AppResult<()> {
    if which(bin).is_none() {
        return Err(AppError::msg(format!(
            "{} support requires the `{}` executable. Install it from {} and ensure it is on your PATH.",
            label, bin, url
        )));
    }
    Ok(())
}

pub fn require_bin_named(bin: &str, label: &str, url: &str, display_bin: &str) -> AppResult<()> {
    if which(bin).is_none() {
        let tail = match label {
            "Java" => format!(" or your vendor of choice and ensure it is on your PATH."),
            "PHP" => " and ensure it is on your PATH.".into(),
            "Swift" => format!(" and ensure `{}` is on your PATH.", display_bin.split_whitespace().next().unwrap_or(display_bin)),
            _ => format!(" and ensure `{}` is on your PATH.", display_bin.split_whitespace().next().unwrap_or(display_bin)),
        };
        let _ = tail;
        // Use a single canonical format close to the reference messages.
        return Err(match label {
            "Java" => AppError::msg(format!(
                "Java support requires the `javac` compiler. Install the JDK from {} or your vendor of choice and ensure it is on your PATH.", url)),
            "Kotlin" => AppError::msg(format!(
                "Kotlin support requires the `kotlinc` compiler. Install it from {} and ensure it is on your PATH.", url)),
            "PHP" => AppError::msg(format!(
                "PHP support requires the `php` CLI executable. Install PHP and ensure it is on your PATH.")),
            "Swift" => AppError::msg(format!(
                "Swift support requires the `swift` executable. Install Xcode command-line tools or the Swift toolchain from {} and ensure `swift` is on your PATH.", url)),
            "R" => AppError::msg(format!(
                "R support requires the `Rscript` executable. Install R from {} and ensure `Rscript` is on your PATH.", url)),
            "Haskell" => AppError::msg(format!(
                "Haskell support requires the `runghc` executable. Install the GHC toolchain from {} (or via ghcup) and ensure `runghc` is on your PATH.", url)),
            _ => AppError::msg(format!(
                "{} support requires the `{}` executable. Install it from {} and ensure it is on your PATH.", label, bin, url)),
        });
    }
    Ok(())
}

pub fn require_deno(ctx: &str) -> AppResult<()> {
    if which("deno").is_none() {
        return Err(AppError::msg(format!(
            "failed to run Deno for {} execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.",
            ctx
        )));
    }
    Ok(())
}

pub fn require_cc() -> AppResult<()> {
    if which("cc").is_none() && which("gcc").is_none() && which("clang").is_none() {
        return Err(AppError::msg(
            "C support requires a C compiler (cc/gcc/clang). Install one and ensure it is on your PATH.".to_string()
        ));
    }
    Ok(())
}

pub fn require_cxx() -> AppResult<()> {
    if which("c++").is_none() && which("g++").is_none() && which("clang++").is_none() {
        return Err(AppError::msg(
            "C++ support requires a C++ compiler (c++/g++/clang++). Install one and ensure it is on your PATH.".to_string()
        ));
    }
    Ok(())
}

pub fn require_dotnet() -> AppResult<()> {
    if which("dotnet").is_none() {
        return Err(AppError::msg(
            "C# support requires the `dotnet` CLI. Install the .NET SDK from https://dotnet.microsoft.com/download and ensure `dotnet` is on your PATH.".to_string()
        ));
    }
    Ok(())
}

pub fn which(bin: &str) -> Option<PathBuf> {
    let path_env = std::env::var_os("PATH")?;
    for dir in std::env::split_paths(&path_env) {
        let full = dir.join(bin);
        if let Ok(md) = std::fs::metadata(&full) {
            if md.is_file() && md.permissions().readonly() == false {
                return Some(full);
            }
            if md.is_file() {
                return Some(full);
            }
        }
    }
    None
}

fn status_exit(s: std::io::Result<std::process::ExitStatus>, label: &str) -> Result<i32, AppError> {
    match s {
        Ok(st) => Ok(st.code().unwrap_or(1)),
        Err(e) => Err(AppError::wrap(format!("failed to invoke {}", label), e)),
    }
}

// ---------- language runners (inline) ----------

fn run_bash_inline(code: &str) -> AppResult<i32> {
    require_bin("bash", "Bash", "https://www.gnu.org/software/bash/")?;
    let s = Command::new("bash").arg("-c").arg(code).status();
    status_exit(s, "bash")
}
fn run_python_inline(code: &str) -> AppResult<i32> {
    require_bin("python3", "Python", "https://www.python.org/downloads/")?;
    let s = Command::new("python3").arg("-c").arg(code).status();
    status_exit(s, "python3")
}
fn run_perl_inline(code: &str) -> AppResult<i32> {
    require_bin("perl", "Perl", "https://www.perl.org/get.html")?;
    let dir = temp::make_dir("run-perl")
        .map_err(|e| AppError::wrap("failed to create temp dir", e))?;
    let f = dir.join("snippet.pl");
    std::fs::write(&f, code).map_err(|e| AppError::wrap("failed to write snippet", e))?;
    let s = Command::new("perl").arg(&f).status();
    status_exit(s, "perl")
}
fn run_ruby_inline(code: &str) -> AppResult<i32> {
    if which("ruby").is_none() {
        return Err(AppError::wrap("failed to invoke ruby", std::io::Error::from(std::io::ErrorKind::NotFound)));
    }
    let s = Command::new("ruby").arg("-e").arg(code).status();
    status_exit(s, "ruby")
}
fn run_js_inline(code: &str) -> AppResult<i32> {
    if which("node").is_none() {
        return Err(AppError::wrap("failed to invoke node", std::io::Error::from(std::io::ErrorKind::NotFound)));
    }
    let s = Command::new("node").arg("-e").arg(code).status();
    status_exit(s, "node")
}
fn run_ts_inline(code: &str, _file: bool) -> AppResult<i32> {
    require_deno("inline")?;
    let dir_root = std::env::temp_dir();
    let tmp = dir_root.join(format!(".tmp{}", random_name(6)));
    std::fs::write(&tmp, code).map_err(|e| AppError::wrap("failed to write snippet", e))?;
    let s = Command::new("deno")
        .arg("run").arg("--quiet").arg("--no-check").arg("--ext").arg("ts").arg(&tmp).status();
    status_exit(s, "deno")
}
fn run_lua_inline(code: &str) -> AppResult<i32> {
    require_bin_named("lua", "Lua", "https://www.lua.org/download.html", "lua")?;
    let dir = temp::make_dir("run-lua").map_err(|e| AppError::wrap("failed to create temp dir", e))?;
    let f = dir.join("snippet.lua");
    std::fs::write(&f, code).map_err(|e| AppError::wrap("failed to write snippet", e))?;
    let s = Command::new("lua").arg(&f).status();
    status_exit(s, "lua")
}
fn run_r_inline(code: &str) -> AppResult<i32> {
    require_bin_named("Rscript", "R", "https://cran.r-project.org/", "Rscript")?;
    let dir = temp::make_dir("run-r").map_err(|e| AppError::wrap("failed to create temp dir", e))?;
    let f = dir.join("snippet.R");
    std::fs::write(&f, code).map_err(|e| AppError::wrap("failed to write snippet", e))?;
    let s = Command::new("Rscript").arg("--vanilla").arg(&f).status();
    status_exit(s, "Rscript")
}
fn run_go_inline(code: &str) -> AppResult<i32> {
    require_bin("go", "Go", "https://go.dev/doc/install")?;
    let dir = temp::make_dir("run-go").map_err(|e| AppError::wrap("failed to create temp dir", e))?;
    let f = dir.join("main.go");
    std::fs::write(&f, code).map_err(|e| AppError::wrap("failed to write snippet", e))?;
    let s = Command::new("go").current_dir(&dir).arg("run").arg("main.go").status();
    status_exit(s, "go")
}
fn run_rust_inline(code: &str) -> AppResult<i32> {
    run_rust_inline_with_name(code, "main.rs")
}
fn run_rust_inline_with_name(code: &str, _name_hint: &str) -> AppResult<i32> {
    require_bin("rustc", "Rust", "https://www.rust-lang.org/tools/install")?;
    let dir = temp::make_dir("run-rust").map_err(|e| AppError::wrap("failed to create temp dir", e))?;
    let f = dir.join("main.rs");
    std::fs::write(&f, code).map_err(|e| AppError::wrap("failed to write snippet", e))?;
    let bin = dir.join("run_rust_binary");
    let cs = Command::new("rustc")
        .arg("--color=never").arg("--edition=2021").arg("--crate-name").arg("run_snippet")
        .arg(&f).arg("-o").arg(&bin).status();
    let st = cs.map_err(|e| AppError::wrap("failed to invoke rustc", e))?;
    if !st.success() {
        return Ok(st.code().unwrap_or(1));
    }
    let s = Command::new(&bin).status()
        .map_err(|e| AppError::wrap(format!("failed to execute compiled binary {}", bin.display()), e))?;
    Ok(s.code().unwrap_or(1))
}
fn run_c_inline(code: &str) -> AppResult<i32> {
    require_cc()?;
    let dir = temp::make_dir("run-c").map_err(|e| AppError::wrap("failed to create temp dir", e))?;
    let f = dir.join("main.c");
    let src = if needs_c_wrap(code) {
        format!("#include <stdio.h>\n\nint main(void)\n{{\n    {}\n    return 0;\n}}\n", code.trim_end_matches('\n'))
    } else {
        code.to_string()
    };
    std::fs::write(&f, &src).map_err(|e| AppError::wrap("failed to write snippet", e))?;
    let bin = dir.join("run_c_binary");
    let cc = which("cc").or_else(|| which("gcc")).or_else(|| which("clang"))
        .ok_or_else(|| AppError::msg("no C compiler"))?;
    let st = Command::new(&cc)
        .arg(&f).arg("-std=c11").arg("-O0").arg("-Wall").arg("-Wextra").arg("-o").arg(&bin).status()
        .map_err(|e| AppError::wrap("failed to invoke C compiler", e))?;
    if !st.success() {
        return Ok(st.code().unwrap_or(1));
    }
    let s = Command::new(&bin).status()
        .map_err(|e| AppError::wrap(format!("failed to execute compiled binary {}", bin.display()), e))?;
    Ok(s.code().unwrap_or(1))
}
fn needs_c_wrap(code: &str) -> bool {
    // If the code contains `main(` it's considered a full program.
    !code.contains("main(")
}
fn run_cpp_inline(code: &str) -> AppResult<i32> {
    require_cxx()?;
    let dir = temp::make_dir("run-cpp").map_err(|e| AppError::wrap("failed to create temp dir", e))?;
    let f = dir.join("main.cpp");
    std::fs::write(&f, code).map_err(|e| AppError::wrap("failed to write snippet", e))?;
    let bin = dir.join("run_cpp_binary");
    let cc = which("c++").or_else(|| which("g++")).or_else(|| which("clang++"))
        .ok_or_else(|| AppError::msg("no C++ compiler"))?;
    let st = Command::new(&cc)
        .arg(&f).arg("-std=c++17").arg("-O0").arg("-Wall").arg("-Wextra").arg("-o").arg(&bin).status()
        .map_err(|e| AppError::wrap("failed to invoke C++ compiler", e))?;
    if !st.success() {
        return Ok(st.code().unwrap_or(1));
    }
    let s = Command::new(&bin).status()
        .map_err(|e| AppError::wrap(format!("failed to execute compiled binary {}", bin.display()), e))?;
    Ok(s.code().unwrap_or(1))
}
fn run_java_inline(code: &str) -> AppResult<i32> {
    require_bin_named("javac", "Java", "https://adoptium.net/", "javac compiler")?;
    let dir = temp::make_dir("run-java").map_err(|e| AppError::wrap("failed to create temp dir", e))?;
    let f = dir.join("Main.java");
    let src = if code.contains("class Main") {
        code.to_string()
    } else {
        format!(
            "public class Main {{\n    public static void main(String[] args) throws Exception {{\n        {}\n    }}\n}}\n",
            code
        )
    };
    std::fs::write(&f, &src).map_err(|e| AppError::wrap("failed to write snippet", e))?;
    let st = Command::new("javac").arg("-d").arg(&dir).arg(&f).status()
        .map_err(|e| AppError::wrap("failed to invoke javac", e))?;
    if !st.success() {
        return Ok(st.code().unwrap_or(1));
    }
    let s = Command::new("java").arg("-cp").arg(&dir).arg("Main").status()
        .map_err(|e| AppError::wrap("failed to invoke java", e))?;
