pub fn which(bin: &str) -> Option<PathBuf> {
    let path_env = std::env::var_os("PATH")?;
    for dir in std::env::split_paths(&path_env) {
        let full = dir.join(bin);
        if let Ok(md) = std::fs::metadata(&full) {
            if md.is_file() && md.permissions().readonly() == false {
                return Some(full);
            }
            if md.is_file() {
                return Some(full);
            }
        }
    }
    None
}

fn status_exit(s: std::io::Result<std::process::ExitStatus>, label: &str) -> Result<i32, AppError> {
    match s {
        Ok(st) => Ok(st.code().unwrap_or(1)),
        Err(e) => Err(AppError::wrap(format!("failed to invoke {}", label), e)),
    }
}

