//! Interactive REPL.

use crate::lang::{self, Lang};
use crate::runner::{self, AppError, AppResult};
use crate::temp;
use crate::detect;

use std::io::{self, BufRead, Read, Write};
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::time::Instant;

pub fn run(initial_lang: Lang, detect_on: bool) -> AppResult<i32> {
    let mut state = ReplState {
        current: initial_lang,
        detect: detect_on,
        pysess: None,
        bashsess: None,
        other_lines: std::collections::HashMap::new(),
    };

    let stdout = io::stdout();
    let stdin = io::stdin();
    let mut stdout = stdout.lock();
    let mut stdin = stdin.lock();

    writeln!(stdout, "run universal REPL. Type :help for commands.").ok();

    let mut line_buf = String::new();
    loop {
        write!(stdout, "{}>>> ", state.current.id()).ok();
        stdout.flush().ok();

        line_buf.clear();
        let n = match stdin.read_line(&mut line_buf) {
            Ok(n) => n,
            Err(_) => 0,
        };
        if n == 0 {
            writeln!(stdout, "bye").ok();
            return Ok(0);
        }
        // Strip \n
        let line = line_buf.trim_end_matches(['\r', '\n']);

        // Empty line → just continue
        if line.trim().is_empty() {
            continue;
        }

        if line.starts_with(':') {
            match handle_command(&mut state, &line[1..], &mut stdout, &mut stdin)? {
                CmdOutcome::Continue => continue,
                CmdOutcome::Quit => return Ok(0),
            }
        }

        // Regular input: possibly multi-line for Python.
        let input = if state.current == Lang::Python {
            read_python_multiline(&mut stdin, &mut stdout, line.to_string())?
        } else {
            line.to_string()
        };

        // Auto-detect language on this input if enabled.
        if state.detect {
            if let Some(det) = detect::detect_from_content(&input) {
                if det != state.current {
                    writeln!(stdout, "[auto-detect] switching {} → {}", state.current.id(), det.id()).ok();
