fn read_python_multiline<R: BufRead, W: Write>(stdin: &mut R, out: &mut W, first: String) -> AppResult<String> {
    let mut buf = String::new();
    buf.push_str(&first);

    loop {
        if !python_needs_more(&buf) {
            return Ok(buf);
        }
        write!(out, "... ").ok();
        out.flush().ok();
        let mut line = String::new();
        let n = stdin.read_line(&mut line).map_err(|e| AppError::wrap("stdin", e))?;
        if n == 0 {
            return Ok(buf);
        }
        let line = line.trim_end_matches(['\r', '\n']).to_string();
        if line.is_empty() {
            return Ok(buf);
        }
        buf.push('\n');
        buf.push_str(&line);
    }
