fn python_needs_more(code: &str) -> bool {
    // Simple heuristic: continue if last non-empty trimmed line ends with ':',
    // or bracket depth > 0 or last char is a backslash (escaped newline).
    let lines: Vec<&str> = code.lines().collect();
    let last = lines.iter().rev().find(|l| !l.trim().is_empty()).map(|s| *s).unwrap_or("");
    if last.trim_end().ends_with(':') {
        return true;
    }
    // bracket depth
    let mut depth = 0i32;
    let mut in_str = false;
    let mut str_ch = '\0';
    for (i, ch) in code.chars().enumerate() {
        if in_str {
            if ch == '\\' { continue; }
            if ch == str_ch { in_str = false; }
            continue;
        }
        match ch {
            '#' => {
                // skip to end of line
                let _ = i;
                // iterate chars until newline - simple
                // This shortcut: just break loop of chars for the line.
            }
            '"' | '\'' => { in_str = true; str_ch = ch; }
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth -= 1,
            _ => {}
        }
    }
    if depth > 0 { return true; }
    if last.trim_end().ends_with('\\') { return true; }

    // If we are inside a multi-line compound (saw a prior line ending with ':'),
    // we need to wait for an empty line; the caller handles that by breaking on empty.
    // Detect: if there exist prior lines, and the most recent non-empty line is indented.
    if lines.len() > 1 {
        if last.starts_with(' ') || last.starts_with('\t') {
            return true;
        }
    }
    false
}

