fn exec_python(state: &mut ReplState, input: &str) -> AppResult<(i32, bool)> {
    if state.pysess.is_none() {
        let dir = temp::make_dir("run-python-repl").map_err(|e| AppError::wrap("tmp", e))?;
        state.pysess = Some(PySession {
            dir,
            body: String::new(),
            last_stdout: String::new(),
            counter: 0,
        });
    }
    let sess = state.pysess.as_mut().unwrap();
    let is_expr = python_is_expression(input);
    let to_append = if is_expr {
        let name = format!("__run_value_{}", sess.counter);
        format!("{} = ({})\nprint(repr({}), flush=True)", name, input, name)
    } else {
        input.to_string()
    };
    sess.counter += 1;

    let mut new_body = String::from("import sys\nfrom math import *\n\n");
    new_body.push_str(&sess.body);
    if !sess.body.is_empty() && !sess.body.ends_with('\n') {
        new_body.push('\n');
    }
    new_body.push_str(&to_append);
    new_body.push('\n');
    let file = sess.dir.join("session.py");
    std::fs::write(&file, &new_body).map_err(|e| AppError::wrap("write", e))?;

    let out = Command::new("python3").arg(&file).output()
        .map_err(|e| AppError::wrap("invoke python3", e))?;
    let stderr = String::from_utf8_lossy(&out.stderr).to_string();
    let stdout = String::from_utf8_lossy(&out.stdout).to_string();

    // Print stderr as-is
    if !stderr.is_empty() {
        eprint!("{}", stderr);
    }
    // Print new portion of stdout
    let delta = diff_tail(&sess.last_stdout, &stdout);
    print!("{}", delta);
    std::io::stdout().flush().ok();

    let success = out.status.success();
    let exit = out.status.code().unwrap_or(if success { 0 } else { 1 });
    if success {
        // Persist the new body and output baseline.
        sess.body.push_str(&to_append);
        sess.body.push('\n');
        sess.last_stdout = stdout;
    }
    Ok((exit, false))
}

fn diff_tail<'a>(prev: &str, new: &'a str) -> &'a str {
    if new.starts_with(prev) {
        &new[prev.len()..]
    } else {
        new
    }
}

fn python_is_expression(code: &str) -> bool {
    // Use python3 -c "compile(..., 'eval')" to check.
    let out = Command::new("python3")
        .arg("-c")
        .arg("import sys; compile(sys.stdin.read(), '<stdin>', 'eval')")
        .stdin(Stdio::piped())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn();
    let Ok(mut child) = out else { return false; };
    if let Some(mut si) = child.stdin.take() {
        let _ = si.write_all(code.as_bytes());
        drop(si);
    }
    match child.wait() {
        Ok(s) => s.success(),
        Err(_) => false,
    }
}

fn exec_bash(state: &mut ReplState, input: &str) -> AppResult<(i32, bool)> {
    if state.bashsess.is_none() {
        let dir = temp::make_dir("run-bash-repl").map_err(|e| AppError::wrap("tmp", e))?;
        state.bashsess = Some(BashSession {
            dir,
            body: String::from("#!/usr/bin/env bash\nset -e\n"),
            last_stdout: String::new(),
        });
    }
    let sess = state.bashsess.as_mut().unwrap();
    let mut new_body = sess.body.clone();
    new_body.push_str(input);
    new_body.push('\n');
    let file = sess.dir.join("session.sh");
    std::fs::write(&file, &new_body).map_err(|e| AppError::wrap("write", e))?;
    let out = Command::new("bash").arg(&file).output()
        .map_err(|e| AppError::wrap("invoke bash", e))?;
    let stderr = String::from_utf8_lossy(&out.stderr).to_string();
    let stdout = String::from_utf8_lossy(&out.stdout).to_string();
    if !stderr.is_empty() { eprint!("{}", stderr); }
    let delta = diff_tail(&sess.last_stdout, &stdout);
    print!("{}", delta);
    std::io::stdout().flush().ok();
    let success = out.status.success();
    let exit = out.status.code().unwrap_or(if success {0} else {1});
    if success {
        sess.body = new_body;
        sess.last_stdout = stdout;
    }
    Ok((exit, false))
}

fn exec_other(state: &mut ReplState, input: &str) -> AppResult<(i32, bool)> {
    // For simpler languages we just run the input as if it were a snippet.
    let res = runner::run_inline(state.current, input);
    match res {
        Ok(code) => Ok((code, false)),
        Err(e) => {
            eprintln!("Error: {}", e.msg);
            // Error already printed; suppress the [exit code] line.
            Ok((1, true))
        }
    }
}
