        }
        "reset" => {
            state.pysess = None;
            state.bashsess = None;
            state.other_lines.clear();
            writeln!(out, "session for '{}' reset", state.current.id()).ok();
            Ok(CmdOutcome::Continue)
        }
        "load" => {
            if rest.is_empty() {
                writeln!(out, "usage: :load <path>").ok();
                return Ok(CmdOutcome::Continue);
            }
            let path = PathBuf::from(rest);
            let started = Instant::now();
            let res = runner::run_file(state.current, &path);
            let ms = started.elapsed().as_millis();
            match res {
                Ok(code) => {
                    if code != 0 {
                        writeln!(out, "[exit code {}] ({}ms)", code, ms).ok();
                    }
                }
                Err(e) => {
                    eprintln!("Error: {}", e.msg);
                }
            }
            Ok(CmdOutcome::Continue)
        }
        "exit" | "quit" => Ok(CmdOutcome::Quit),
        other => {
            // Language id or alias?
            if let Some(l) = lang::parse_lang(other) {
                if l == state.current {
                    writeln!(out, "already using {}", l.id()).ok();
                } else {
                    state.current = l;
                    state.pysess = None;
                    state.bashsess = None;
                    state.other_lines.clear();
                    writeln!(out, "switched to {}", l.id()).ok();
                }
                Ok(CmdOutcome::Continue)
            } else {
                writeln!(out, "unknown command: :{}. Type :help for help.", other).ok();
                Ok(CmdOutcome::Continue)
            }
        }
    }
}

fn switch_language<W: Write>(state: &mut ReplState, arg: &str, out: &mut W) -> AppResult<()> {
    match lang::parse_lang(arg) {
        Some(l) => {
            if l == state.current {
                writeln!(out, "already using {}", l.id()).ok();
            } else {
                state.current = l;
                state.pysess = None;
                state.bashsess = None;
                state.other_lines.clear();
                writeln!(out, "switched to {}", l.id()).ok();
            }
            Ok(())
        }
        None => {
            Err(AppError::msg(format!(
                "language '{}' not supported. Available: {}",
                arg, lang::available_list()
            )))
        }
    }
}

fn read_python_multiline<R: BufRead, W: Write>(stdin: &mut R, out: &mut W, first: String) -> AppResult<String> {
    let mut buf = String::new();
    buf.push_str(&first);

    loop {
        if !python_needs_more(&buf) {
            return Ok(buf);
        }
        write!(out, "... ").ok();
        out.flush().ok();
        let mut line = String::new();
        let n = stdin.read_line(&mut line).map_err(|e| AppError::wrap("stdin", e))?;
        if n == 0 {
            return Ok(buf);
        }
        let line = line.trim_end_matches(['\r', '\n']).to_string();
        if line.is_empty() {
            return Ok(buf);
        }
        buf.push('\n');
        buf.push_str(&line);
    }
}

fn python_needs_more(code: &str) -> bool {
    // Simple heuristic: continue if last non-empty trimmed line ends with ':',
    // or bracket depth > 0 or last char is a backslash (escaped newline).
    let lines: Vec<&str> = code.lines().collect();
    let last = lines.iter().rev().find(|l| !l.trim().is_empty()).map(|s| *s).unwrap_or("");
    if last.trim_end().ends_with(':') {
        return true;
    }
    // bracket depth
    let mut depth = 0i32;
    let mut in_str = false;
    let mut str_ch = '\0';
    for (i, ch) in code.chars().enumerate() {
        if in_str {
            if ch == '\\' { continue; }
            if ch == str_ch { in_str = false; }
            continue;
        }
        match ch {
            '#' => {
                // skip to end of line
                let _ = i;
                // iterate chars until newline - simple
                // This shortcut: just break loop of chars for the line.
            }
            '"' | '\'' => { in_str = true; str_ch = ch; }
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth -= 1,
            _ => {}
        }
    }
    if depth > 0 { return true; }
    if last.trim_end().ends_with('\\') { return true; }

    // If we are inside a multi-line compound (saw a prior line ending with ':'),
    // we need to wait for an empty line; the caller handles that by breaking on empty.
    // Detect: if there exist prior lines, and the most recent non-empty line is indented.
    if lines.len() > 1 {
        if last.starts_with(' ') || last.starts_with('\t') {
            return true;
        }
    }
    false
}

fn exec_in_repl(state: &mut ReplState, input: &str) -> AppResult<(i32, bool)> {
    match state.current {
        Lang::Python => exec_python(state, input),
        Lang::Bash => exec_bash(state, input),
        _ => exec_other(state, input),
    }
}

fn exec_python(state: &mut ReplState, input: &str) -> AppResult<(i32, bool)> {
    if state.pysess.is_none() {
        let dir = temp::make_dir("run-python-repl").map_err(|e| AppError::wrap("tmp", e))?;
        state.pysess = Some(PySession {
            dir,
            body: String::new(),
            last_stdout: String::new(),
            counter: 0,
        });
    }
    let sess = state.pysess.as_mut().unwrap();
    let is_expr = python_is_expression(input);
    let to_append = if is_expr {
        let name = format!("__run_value_{}", sess.counter);
        format!("{} = ({})\nprint(repr({}), flush=True)", name, input, name)
    } else {
        input.to_string()
    };
    sess.counter += 1;

    let mut new_body = String::from("import sys\nfrom math import *\n\n");
    new_body.push_str(&sess.body);
    if !sess.body.is_empty() && !sess.body.ends_with('\n') {
        new_body.push('\n');
    }
    new_body.push_str(&to_append);
    new_body.push('\n');
    let file = sess.dir.join("session.py");
    std::fs::write(&file, &new_body).map_err(|e| AppError::wrap("write", e))?;

    let out = Command::new("python3").arg(&file).output()
        .map_err(|e| AppError::wrap("invoke python3", e))?;
    let stderr = String::from_utf8_lossy(&out.stderr).to_string();
    let stdout = String::from_utf8_lossy(&out.stdout).to_string();

    // Print stderr as-is
    if !stderr.is_empty() {
        eprint!("{}", stderr);
    }
    // Print new portion of stdout
    let delta = diff_tail(&sess.last_stdout, &stdout);
    print!("{}", delta);
    std::io::stdout().flush().ok();

    let success = out.status.success();
    let exit = out.status.code().unwrap_or(if success { 0 } else { 1 });
    if success {
        // Persist the new body and output baseline.
        sess.body.push_str(&to_append);
        sess.body.push('\n');
        sess.last_stdout = stdout;
    }
    Ok((exit, false))
}

fn diff_tail<'a>(prev: &str, new: &'a str) -> &'a str {
    if new.starts_with(prev) {
        &new[prev.len()..]
    } else {
        new
    }
}

fn python_is_expression(code: &str) -> bool {
    // Use python3 -c "compile(..., 'eval')" to check.
    let out = Command::new("python3")
        .arg("-c")
        .arg("import sys; compile(sys.stdin.read(), '<stdin>', 'eval')")
        .stdin(Stdio::piped())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn();
    let Ok(mut child) = out else { return false; };
    if let Some(mut si) = child.stdin.take() {
        let _ = si.write_all(code.as_bytes());
        drop(si);
    }
    match child.wait() {
        Ok(s) => s.success(),
        Err(_) => false,
    }
}

fn exec_bash(state: &mut ReplState, input: &str) -> AppResult<(i32, bool)> {
    if state.bashsess.is_none() {
        let dir = temp::make_dir("run-bash-repl").map_err(|e| AppError::wrap("tmp", e))?;
        state.bashsess = Some(BashSession {
            dir,
            body: String::from("#!/usr/bin/env bash\nset -e\n"),
            last_stdout: String::new(),
        });
    }
    let sess = state.bashsess.as_mut().unwrap();
    let mut new_body = sess.body.clone();
    new_body.push_str(input);
    new_body.push('\n');
    let file = sess.dir.join("session.sh");
    std::fs::write(&file, &new_body).map_err(|e| AppError::wrap("write", e))?;
    let out = Command::new("bash").arg(&file).output()
        .map_err(|e| AppError::wrap("invoke bash", e))?;
    let stderr = String::from_utf8_lossy(&out.stderr).to_string();
    let stdout = String::from_utf8_lossy(&out.stdout).to_string();
    if !stderr.is_empty() { eprint!("{}", stderr); }
    let delta = diff_tail(&sess.last_stdout, &stdout);
    print!("{}", delta);
    std::io::stdout().flush().ok();
    let success = out.status.success();
    let exit = out.status.code().unwrap_or(if success {0} else {1});
    if success {
        sess.body = new_body;
        sess.last_stdout = stdout;
    }
    Ok((exit, false))
}

fn exec_other(state: &mut ReplState, input: &str) -> AppResult<(i32, bool)> {
    // For simpler languages we just run the input as if it were a snippet.
    let res = runner::run_inline(state.current, input);
    match res {
        Ok(code) => Ok((code, false)),
        Err(e) => {
            eprintln!("Error: {}", e.msg);
            // Error already printed; suppress the [exit code] line.
            Ok((1, true))
        }
    }
}
